#include <iostream>
#include <string>
using namespace std;

int stock = 8;

void take(int n) {

    /* ① 先看清楚：要的比现有的多，就扔出「不够了」这句话（这时候账一步都不能动） */
    /* ② 够了才动账：把要的从现有的里减掉 */
    /* ③ 印一行：领走 N，还剩 M */

}

int main() {
    try {
        take(2);
    } catch (string e) {
        cout << "接住：" << e << endl;
    }

    try {
        take(100);
    } catch (string e) {
        cout << "接住：" << e << endl;
    }

    cout << "仓库里还是 " << stock << endl;
    return 0;
}

